using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;

// Explicit, one-time authoring migration; source package hashes are regenerated by Unity.
public static class StopUturnMapEdits {
 const string Prefix="reviewed:2026-10-30:";
 static MapPoint P(Vector3 p){return new MapPoint{x=p.x,z=p.z};}
 static RoadMapEvidence Evidence(string note){return new RoadMapEvidence{state="game",checkedAt="2026-10-30",note=note+" 기존 게임 접근 방향/폭에서 산출한 공통 평면이며 현장 실측 위치 아님."};}
 public static void CorrectMetadata(){
  string root=ProjectMapBuild.Root;var p=ProjectMapStore.Load(root);var changed=p.document.facilities.Where(f=>f.id.StartsWith(Prefix)&&f.kind=="stopLine"&&f.evidence.appearanceConfirmed).ToArray();if(changed.Length==0)return;string token=ProjectMapStore.Fingerprint(root);foreach(var f in changed)f.evidence=Evidence("주행 접근 방향의 단일 정지선: 렌더·법규·NPC 공통 평면.");p.document.revision++;p.document.savedAt=DateTime.UtcNow.ToString("o");p.document.projectRevision="";p.contentHash=ProjectMapPackage.Digest(JsonUtility.ToJson(p.document));ProjectMapStore.Save(root,p,token);
 }

 static void StopPlanes(ProjectMapPackage p,string id){
  var j=p.baseline.junctionRules.First(r=>r.id==id);var d=p.document;var axis=new Vector3(j.dx,0,j.dz).normalized;float[] widths={3,3};
  foreach(var a in j.approaches){var f=new Vector3(a.dx,0,a.dz).normalized;int k=Mathf.Abs(Vector3.Dot(f,axis))>.7f?0:1;widths[k]=Mathf.Max(widths[k],a.width*.5f);}
  var facilities=d.facilities.ToList();
  foreach(var a in j.approaches){var f=new Vector3(a.dx,0,a.dz).normalized;int k=Mathf.Abs(Vector3.Dot(f,axis))>.7f?0:1,sign=Vector3.Dot(f,k==0?axis:TrafficSystem.Right(axis))>=0?1:-1;
   facilities.RemoveAll(x=>x.junctionId==id&&x.axis==k&&x.sign==sign&&x.kind=="stopLine");
   var cross=j.V()-f*(widths[1-k]+TrafficJunction.CrosswalkCentreOffset);var stop=j.V()-f*(widths[1-k]+4)+TrafficSystem.Right(f)*(a.width*.25f);
   facilities.Add(new RoadMapFacility{id=Prefix+id+":"+k+":"+sign+":stop",kind="stopLine",junctionId=id,axis=k,sign=sign,x=stop.x,z=stop.z,yaw=Quaternion.LookRotation(f).eulerAngles.y,width=a.width*.5f-.3f,length=.4f,evidence=Evidence("주행 접근 방향의 단일 정지선: 렌더·법규·NPC 공통 평면.")});
  }d.facilities=facilities.ToArray();
 }
 static int ResampleAt(RoadMapLane lane,float cut){
  var path=new AssistedRoadNetwork.Path(lane.points.Select((p,i)=>p.V(lane.heights!=null&&i<lane.heights.Length?lane.heights[i]:0)).ToArray());
  var positions=new List<Vector3>();for(float at=0;at<cut-.01f;at+=1)positions.Add(path.Position(at));int index=positions.Count;positions.Add(path.Position(cut));for(float at=cut+1;at<path.length-.01f;at+=1)positions.Add(path.Position(at));positions.Add(path.Position(path.length));
  lane.points=positions.Select(P).ToArray();lane.heights=positions.Select(q=>q.y).ToArray();return index;
 }
 static void MoveUturn(ProjectMapPackage p,string name){
  var d=p.document;var join=d.lanes.First(l=>l.id=="join:reviewed:"+name+":uturn");var from=d.lanes.Single(l=>!l.disabled&&l.next.Contains(join.id));var target=d.lanes.Single(l=>l.id==join.next[0]);var condition=UturnMovement.Condition(d,from.id);
  var originalEnd=from.points.Last().V();var originalTarget=target.points[0].V();float remaining=10,length;
  // Imported approaches can consist of short ordinary segments. Walk the
  // existing directed chain before choosing the interior split station.
  while(true){length=new AssistedRoadNetwork.Path(from.points.Select(q=>q.V()).ToArray()).length;if(length>remaining+.05f)break;remaining-=length;var first=from.points[0].V();var chainHeading=(from.points[1].V()-first).normalized;var current=from;
   from=d.lanes.Single(l=>!l.disabled&&l.turn==0&&l.change==0&&!l.id.StartsWith("join:")&&l.next.Contains(current.id)&&(l.points.Last().V()-first).sqrMagnitude<.01f&&Vector3.Dot((l.points.Last().V()-l.points[l.points.Length-2].V()).normalized,chainHeading)>.98f);
  }
  int cut=ResampleAt(from,length-remaining);string incomingTail=RoadMapAuthoringOperations.SplitLane(d,from.id,cut);
  foreach(var lane in d.lanes)lane.next=lane.next.Where(n=>n!=join.id).ToArray();from.next=from.next.Concat(new[]{join.id}).ToArray();from.ruleId=join.ruleId;condition.laneId=from.id;
  float exitLength=new AssistedRoadNetwork.Path(target.points.Select(q=>q.V()).ToArray()).length;RoadMapLane to;
  if(Mathf.Abs(exitLength-10)<.05f){
   // The existing exit already ends at the requested station; reuse its
   // ordinary continuation rather than splitting at a duplicate endpoint.
   to=d.lanes.Single(l=>target.next.Contains(l.id)&&!l.disabled&&l.turn==0&&l.change==0&&!l.id.StartsWith("join:")&&(l.points[0].V()-target.points.Last().V()).sqrMagnitude<.01f);
  }else{if(exitLength<10.1f)throw new InvalidOperationException("Uturn exit requires an interior cut or exact existing station");int exitCut=ResampleAt(target,10);string outgoingTail=RoadMapAuthoringOperations.SplitLane(d,target.id,exitCut);to=d.lanes.Single(l=>l.id==outgoingTail);}
  join.next=new[]{to.id};join.fromNode=from.toNode;join.toNode=to.fromNode;
  var curve=UturnMovement.Geometry(from,to);join.points=curve.Select(P).ToArray();join.heights=curve.Select(q=>q.y).ToArray();join.evidence.note+=" 2026-10-30: 횡단보도 전 분기/합류10m 상류 이동. 곡선 및 노면 허용 구간은 게임 추정.";
  var heading=(from.points.Last().V()-from.points[from.points.Length-2].V()).normalized;var sign=from.points.Last().V()-heading*7-TrafficSystem.Right(heading)*2.3f;condition.x=sign.x;condition.z=sign.z;
  Debug.Log("STOP_UTURN_RELOCATED "+name+" before="+originalEnd+" after="+from.points.Last().V()+" exitBefore="+originalTarget+" exitAfter="+to.points[0].V());
 }
 public static void Apply(){
  string root=ProjectMapBuild.Root,token=ProjectMapStore.Fingerprint(root);var p=ProjectMapStore.Load(root);
  if(p.document.facilities.Any(f=>f.id.StartsWith(Prefix)))throw new InvalidOperationException("Stop/Uturn migration already applied; do not split a second time.");
  foreach(string id in new[]{"J1927_5181","J7973_3744","J8066_6364"})StopPlanes(p,id);
  MoveUturn(p,"J8066-S");MoveUturn(p,"J7973-E");
  var objects=p.document.scene.objects.ToList();objects.Add(new ProjectMapObject{id=Prefix+"J7973-SE-island",kind="sidewalk",name="관찰 교통섬 · 게임 치수",height=.16f,points=new[]{P(new Vector3(810.5f,0,354.5f)),P(new Vector3(817,0,356.3f)),P(new Vector3(810.5f,0,357))}});p.document.scene.objects=objects.ToArray();
  RoadMapAuthoringOperations.RemapServiceBindings(p.document);p.document.revision++;p.document.savedAt=DateTime.UtcNow.ToString("o");p.document.projectRevision="";p.contentHash=ProjectMapPackage.Digest(JsonUtility.ToJson(p.document));ProjectMapStore.Save(root,p,token);ProjectMapBuild.Prepare();
  Debug.Log("STOP_UTURN_MAP_APPLIED source="+ProjectMapStore.Fingerprint(root));
 }
}
